async function readObservations(){const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),5000);try{const r=await fetch(activeEndpoint,{signal:abort.signal,cache:'no-store'});if(!r.ok)throw new Error('상태 주소에서 응답하지 않습니다.');const o=await r.json();if(!o.observedAt||!o.seats)throw new Error('observedAt, seats 필드가 필요합니다.');const age=Date.now()-Date.parse(o.observedAt);if(!Number.isFinite(age)||age>65000||age< -60000)throw new Error('관찰기 데이터가 최신 상태가 아닙니다.');observations=o;const previous=JSON.stringify(states);source='live';states=Object.fromEntries(seats.map(s=>{let rec=o.seats[s.id];let value=typeof rec==='string'?rec:rec?.state;return [s.id,['online','no-response','unknown'].includes(value)?value:'unknown']}));$('#connection-message').textContent=`마지막 확인 ${new Date(o.observedAt).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul'})} · ${o.devices?.length||0}개 후보 기기 · 자리별 PC 연결이 필요합니다.`;if(previous!==JSON.stringify(states)&&(['space','network','edit'].includes(tab)))build(false);else{updateLists();updateStatus()}}catch(e){unknown();$('#connection-message').textContent='연결할 수 없습니다. '+(e.name==='AbortError'?'응답 시간을 초과했습니다.':e.message)+' 예시 상태는 실제 관측으로 표시되지 않습니다.'}finally{clearTimeout(timer)}}
async function connect(url){try{const u=new URL(url,location.href);if(!['http:','https:'].includes(u.protocol))throw new Error();activeEndpoint=u.href;clearInterval(pollTimer);await readObservations();pollTimer=setInterval(readObservations,20000)}catch{toast('올바른 관찰기 URL을 입력해 주세요.')}}
$('#connect').onclick=()=>connect($('#endpoint').value);$('#local-connect').onclick=()=>{let u=location.hostname==='127.0.0.1'||location.hostname==='localhost'?location.origin+'/api/status':'http://127.0.0.1:5178/api/status';$('#endpoint').value=u;connect(u)};$('#demo').onclick=()=>{clearInterval(pollTimer);observations=null;source='demo';states={...demoStates};$('#connection-message').textContent='예시 상태입니다. 실제 기기 상태를 나타내지 않습니다.';build(false)};
renderer.domElement.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];transition=null});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5||!['space','edit'].includes(tab))return;let r=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);for(let hit of ray.intersectObject(model,true)){let obj=hit.object;while(obj&&obj!==model){if(tab==='edit'&&obj.userData.layoutId){editor.select({kind:obj.userData.layoutKind,id:obj.userData.layoutId});return}if(obj.userData.seat){seatDetail(seats.find(s=>s.id===obj.userData.seat));return}if(obj.userData.furniture){selected=furniture.find(f=>f.id===obj.userData.furniture);switchTab('furniture');return}obj=obj.parent}}});
const profiler=createProfiler(renderer,'studio',()=>tab);
let last=0;function animate(t){requestAnimationFrame(animate);if(document.hidden||t-last<33)return;last=t;const perfStart=profiler.begin();let rendered=false;if(transition){dirty=true;let v=Math.min(1,(t-transition.start)/650);let f=v*v*(3-2*v);camera.position.lerpVectors(transition.from,transition.to,f);controls.target.lerpVectors(transition.fromTarget,transition.target,f);if(v===1)transition=null}controls.update();if(animatedRigs.length){dirty=shadowDirty=true;for(const rig of animatedRigs){if(rig.updateWork)rig.updateWork(t);else{rig.hands.forEach((h,i)=>h.rotation.x=Math.sin(t*.005+i*2)*.05);if(rig.head)rig.head.rotation.x=.015*Math.sin(t*.0017)}}}if(tab==='people'&&walking&&model.userData.walkDuration){model.userData.gait(t*.001*Math.PI*2/model.userData.walkDuration,true);dirty=shadowDirty=true}if(tab==='people'&&!walking&&!seated&&model.userData.idle){model.userData.idle(t*.001);dirty=shadowDirty=true}if(dirty){renderer.shadowMap.needsUpdate=shadowDirty;renderer.render(scene,camera);dirty=shadowDirty=false;rendered=true}profiler.end(perfStart,rendered)}
editor=createEditor({getLayout:()=>layout,onChange:l=>{layout=l;if(['space','network','edit'].includes(tab))build(false)},onSave:async l=>{localStorage.setItem('conict-layout-v1',JSON.stringify(l));if(['localhost','127.0.0.1'].includes(location.hostname)){const response=await fetch('/api/layout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(l)});if(!response.ok){let message='로컬 저장에 실패했습니다.';try{message=(await response.json()).error||message}catch{}throw new Error(message)}return await response.json()}return {browser:true}},toast});
$('#plan-expand').onclick=()=>{const expanded=document.querySelector('.stage').classList.toggle('plan-expanded');$('#plan-expand').textContent=expanded?'3D 함께 보기':'평면도 확대';editor.refresh();resize();setCamera()};
resize();camera.position.set(11.5,11.6,15.6);build();requestAnimationFrame(animate);
if(['localhost','127.0.0.1'].includes(location.hostname)){activeEndpoint=location.origin+'/api/status';readObservations();pollTimer=setInterval(readObservations,20000);$('#batch').hidden=false;fetch('/api/layout').then(r=>r.json()).then(result=>{if(result.layout&&(!layout.updatedAt||Date.parse(result.layout.updatedAt)>Date.parse(layout.updatedAt))){const same=JSON.stringify({...layout,updatedAt:null})===JSON.stringify({...result.layout,updatedAt:null});if(same){layout.updatedAt=result.layout.updatedAt;localStorage.setItem('conict-layout-v1',JSON.stringify(layout))}else editor.replace(result.layout)}}).catch(()=>{})}
$('#batch').onclick=async()=>{
 const old={mode,tab,selected,person,seated,states:{...states},source,focus};clearInterval(pollTimer);$('#batch').disabled=true;let count=0;
 async function capture(name,png=true){if(transition){camera.position.copy(transition.to);controls.target.copy(transition.target);transition=null}controls.update();model.updateMatrixWorld(true);renderer.shadowMap.needsUpdate=true;renderer.render(scene,camera);if(png){const b=await new Promise(r=>renderer.domElement.toBlob(r));await download(b,name+'.png')}let output=await new GLTFExporter().parseAsync(model,{binary:true,onlyVisible:true});await download(new Blob([output],{type:'model/gltf-binary'}),name+'.glb');count++;$('#batch').textContent='저장 중 '+count+'/'+(2*(1+furniture.length+members.length*2));await new Promise(r=>requestAnimationFrame(r))}
 try{source='demo';states={...demoStates};for(const style of ['polygon','voxel']){mode=style;tab='space';focus='all';build();await capture('conict-space-all-'+mode);tab='furniture';for(const f of furniture){selected=f;build();await capture('conict-furniture-'+f.id+'-'+mode)}tab='people';for(const p of members){person=p;seated=false;build();await capture('conict-people-'+p.id+'-stand-'+mode);seated=true;build();await capture('conict-people-'+p.id+'-sit-'+mode,false)}}toast(`${2*(1+furniture.length+members.length*2)}개 GLB 모델과 ${2*(1+furniture.length+members.length)}개 PNG 시안을 날짜 폴더에 저장했습니다.`)}catch(e){toast('전체 저장 중 문제가 발생했습니다: '+e.message)}finally{({mode,tab,selected,person,seated,states,source,focus}=old);$('#batch').disabled=false;$('#batch').textContent='전체 시안 저장';switchTab(tab);$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(source!=='demo')pollTimer=setInterval(readObservations,20000)}
};
window.addEventListener('storage',e=>{if(e.key==='conict-seat-members'&&e.newValue){try{readSeatAssignments();build(false)}catch{}return}if(e.key==='conict-layout-v1'&&e.newValue){try{const next=validateLayout(JSON.parse(e.newValue));if(Date.parse(next.updatedAt)>Date.parse(layout.updatedAt||'')){const same=JSON.stringify({...next,updatedAt:null})===JSON.stringify({...layout,updatedAt:null});if(same)layout.updatedAt=next.updatedAt;else editor.replace(next)}}catch{}}});
window.addEventListener('beforeunload',()=>clearInterval(pollTimer));

function syncEditingAccess(){
 const button=$('[data-tab="edit"]'),disabled=compactUI();
 button.disabled=disabled;button.setAttribute('aria-disabled',String(disabled));
 button.title=disabled?'공간 편집은 PC에서 이용해 주세요.':'공간 편집';
 if(disabled&&tab==='edit'){toast('공간 편집은 PC에서 이용해 주세요.');switchTab('space')}
}
window.addEventListener('lab-device-change',syncEditingAccess);
syncEditingAccess();
if(['#edit','#furniture','#people','#network'].includes(location.hash))switchTab(location.hash.slice(1));
